const IMAGE_VALUES = Object.values(IMAGES) as string[];

/** Stable photo for an arbitrary key (e.g. a shift id), so generated content looks curated. */
export function photoFor(seed: string): string {
  let h = 2166136261;
  for (let i = 0; i < seed.length; i++) h = Math.imul(h ^ seed.charCodeAt(i), 16777619);
  return IMAGE_VALUES[(h >>> 0) % IMAGE_VALUES.length];
}
